                 int offset = op.c();
                 int count = le32(strings, offset);
                 float[] thresholds = new float[count];
                 for (int i = 0; i < count; i++) {
                     thresholds[i] = Float.intBitsToFloat(le32(strings, offset + 4 + i * 4));
                 }
                 return thresholds;
             }
         }
         throw new AssertionError("no FIT_QUERY for slot " + slotId);
     }

