 const hex = (v: number): string => `0x${(v >>> 0).toString(16)}`;
 const f32 = (bits: number): number => new Float32Array(new Uint32Array([bits]).buffer)[0] ?? 0;
 const name = (table: Record<number, string>, id: number): string => table[id] ?? hex(id);

