         for (op: Opcode in frame.opcodes()) {
             if (op.category() == Categories.PARAMETER &&
                 op.command() == Commands.Parameter.SET_PROPERTY &&
                 op.a() == nodeId &&
                 (op.b() and 0xFFFF) == property
             ) {
