         if let Some(v) = self.token_ref(property_id::FONT_FAMILY) {
             css.push_str(&format!("font-family:{v};"));
         } else if let Some(family) = self.strings.get(&property_id::FONT_FAMILY) {
             css.push_str(&format!("font-family:'{}';", family.replace('\'', "\\'")));
