   let info = BORDER.get(el);
   if (!info) {
     info = { width: 0, color: "rgb(0,0,0)" };
     BORDER.set(el, info);
   }
   return info;
 }
 function transformOf(el: HTMLElement): TransformInfo {
   let info = TRANSFORM.get(el);
   if (!info) {
     info = { translateX: 0, translateY: 0, rotate: 0, scale: 1 };
