     borderOf(el).color = value;
     applyBorderEdges(el);
     return;
   }
   if (property === P.PROP_BORDER_WIDTH) {
     borderOf(el).width = value;
     applyBorderEdges(el);
     return;
   }
   if (property === P.PROP_SHADOW_COLOR) {
     shadowOf(el).color = value;
     recomposeShadow(el);
     return;
   }
   if (property === P.PROP_SHADOW_X) {
     shadowOf(el).x = value;
     recomposeShadow(el);
     return;
   }
   if (property === P.PROP_SHADOW_Y) {
     shadowOf(el).y = value;
     recomposeShadow(el);
     return;
   }
   if (property === P.PROP_SHADOW_RADIUS) {
     shadowOf(el).radius = value;
     recomposeShadow(el);
     return;
   }
   const cssProp = TOKEN_STYLE_PROPS[property];
   if (cssProp) {
     setStyleCss(el, cssProp, value);
   }
