 /** Map a {@link WIDTH}/{@link HEIGHT} value (FILL/HUG/fixed px) to CSS. */
 export function sizeCss(value: number): string {
   if (value === P.WIDTH_FILL) {
     return "100%";
   }
   if (value === P.WIDTH_HUG) {
     return "fit-content";
   }
   return fmtFloat(value) + "px";
 }

