             (property_id::FIRST_ITEM_INDEX, value_type::U32, 10u32),
             (property_id::SPACING, value_type::F32, 8.0f32.to_bits()),
             (property_id::GRID_COLUMNS, value_type::F32, 3.0f32.to_bits()),
         ] {
             opcodes.push(Opcode::new(
                 category::PARAMETER,
                 parameter::SET_PROPERTY,
                 0,
                 1,
