     fn media_controller_renders_a_hidden_shell() {
         use pathland_core::value_type;

         let mut opcodes = Vec::new();
         opcodes.push(Opcode::new(category::TREE, tree::CREATE_NODE, 0, 1, component_type::MEDIA_CONTROLLER as u32, 0));
