                 let color = node.u32_property(property_id::COLOR_VALUE, 0xFF00_0000);
                 let hex = format!(
                     "#{:02x}{:02x}{:02x}",
                     (color >> 16) & 0xFF,
                     (color >> 8) & 0xFF,
                     color & 0xFF
                 );
                 format!("<input{data_id} tabindex=\"0\"{event}{aria} class=\"pathland-color pathland-control\" type=\"color\" value=\"{hex}\"{style}>")
             }
             component_type::COMMENT => String::new(),
             _ => String::new(),
         };
         if self.debug_comments {
             format!("{}{}", debug::node_comment(id, node), element)
         } else {
             element
         }
     }
 }

     fn wrap_stack(
         id: u32,
         direction: &str,
         semantic: Option<&'static str>,
         node: &Node,
         children: &str,
         css: &str,
         event: &str,
         aria: &str,
     ) -> String {
         let tag = semantic.unwrap_or("div");
         let alignment = node
             .properties
             .get(&property_id::ALIGNMENT)
             .map(|bits| f32::from_bits(*bits) as u8)
             .unwrap_or(3);
         // ALIGNMENT positions cross-axis children; the default is hug
         // (flex-start), never CSS `align-items: stretch` — only FILL-sized
         // children stretch (they carry `align-self:stretch`/`100%`), LAYOUT.md.
         let align = match alignment {
             0 => "flex-start",
             1 => "center",
             2 => "flex-end",
             _ => "flex-start",
         };
         let combined = format!(
             "display:flex;flex-direction:{direction};align-items:{align};{css}"
         );
         let stack_style = style_attr(&combined);
         format!(
             "<{tag} data-pathland-id=\"{id}\"{}{event}{aria}{stack_style}>{children}</{tag}>",
             slot_attrs(node),
         )
     }

 /// True when a lazy stack carries the window properties that enable
 /// virtualization (spec/LAYOUT.md §Virtual extent).
 fn lazy_windowed(node: &Node) -> bool {
     node.u32_property(property_id::ITEM_COUNT, 0) > 0
         && node.f32_property(property_id::ITEM_EXTENT, 0.0) > 0.0
 }

 /// A windowed lazy stack: the full virtual main-axis extent is reserved as
 /// padding, and only the emitted window's children flow inside it
 /// (spec/LAYOUT.md §Virtual extent). The `data-pathland-lazy*` attributes let
 /// the DOM client derive the visible range and report `VISIBLE_RANGE`.
 /// The app's base padding for one edge (per-edge > uniform > content margins).
 fn lazy_base_padding(node: &Node, side: u16) -> f32 {
     node.f32_property(
         side,
         node.f32_property(property_id::PADDING, node.content_margins().unwrap_or(0.0)),
     )
 }

 fn wrap_lazy_stack(
     id: u32,
     direction: &str,
     vertical: bool,
     semantic: Option<&'static str>,
     node: &Node,
     children: &str,
     child_count: u32,
     css: &str,
     event: &str,
     aria: &str,
 ) -> String {
     let tag = semantic.unwrap_or("div");
     let alignment = node
         .properties
         .get(&property_id::ALIGNMENT)
         .map(|bits| f32::from_bits(*bits) as u8)
         .unwrap_or(3);
     let align = match alignment {
         0 => "flex-start",
         1 => "center",
         2 => "flex-end",
         _ => "flex-start",
     };
     let count = node.u32_property(property_id::ITEM_COUNT, 0);
     let extent = node.f32_property(property_id::ITEM_EXTENT, 0.0);
     let first = node.u32_property(property_id::FIRST_ITEM_INDEX, 0);
     let spacing = node.f32_property(property_id::SPACING, 0.0).max(0.0);
     let stride = extent + spacing;
     let extents = if node.item_extents.is_empty() {
         None
     } else {
         Some(&node.item_extents)
     };
     let first_offset = node.f32_property(property_id::FIRST_ITEM_OFFSET, first as f32 * stride);
     let total_extent = node.f32_property(
         property_id::TOTAL_EXTENT,
         count as f32 * extent + (count.saturating_sub(1) as f32) * spacing,
     );
     let window_extent = match extents {
         Some(values) => {
             let sum: f32 = values.iter().sum();
             sum + (values.len().saturating_sub(1) as f32) * spacing
         }
         None => child_count as f32 * extent + (child_count.saturating_sub(1) as f32) * spacing,
     };
     let leading = first_offset;
     let trailing = (total_extent - first_offset - window_extent).max(0.0);
     let (extra_top, extra_bottom, extra_left, extra_right) = if vertical {
         (leading, trailing, 0.0, 0.0)
     } else {
         (0.0, 0.0, leading, trailing)
     };
     // The virtual extent adds to the app's padding (an inset around the
     // window). The base values ride on data attributes so the DOM client can
     // recompute the virtual padding without double-counting on a delta.
     let base_top = lazy_base_padding(node, property_id::PADDING_TOP);
     let base_bottom = lazy_base_padding(node, property_id::PADDING_BOTTOM);
     let base_left = lazy_base_padding(node, property_id::PADDING_LEFT);
     let base_right = lazy_base_padding(node, property_id::PADDING_RIGHT);
     let padding = format!(
         "padding-top:{}px;padding-bottom:{}px;padding-left:{}px;padding-right:{}px;",
         base_top + extra_top,
         base_bottom + extra_bottom,
         base_left + extra_left,
         base_right + extra_right,
     );
     let combined = format!(
         "display:flex;flex-direction:{direction};align-items:{align};{padding}{css}"
     );
     let stack_style = style_attr(&combined);
     let axis = if vertical { "vertical" } else { "horizontal" };
     let extents_attr = match (node.strings.get(&property_id::ITEM_EXTENTS), extents) {
         (Some(csv), Some(_)) => format!(
             " data-pathland-item-extents=\"{csv}\" data-pathland-first-item-offset=\"{first_offset}px\" data-pathland-total-extent=\"{total_extent}px\""
         ),
         _ => String::new(),
     };
     format!(
         "<{tag} data-pathland-id=\"{id}\"{}{event}{aria}{stack_style} data-pathland-lazy=\"{axis}\" data-pathland-item-count=\"{count}\" data-pathland-item-extent=\"{extent}px\" data-pathland-first-item-index=\"{first}\" data-pathland-item-spacing=\"{spacing}px\" data-pathland-base-padding-top=\"{base_top}px\" data-pathland-base-padding-right=\"{base_right}px\" data-pathland-base-padding-bottom=\"{base_bottom}px\" data-pathland-base-padding-left=\"{base_left}px\"{extents_attr}>{children}</{tag}>",
         slot_attrs(node),
     )
 }

 /// Inline grid CSS: `display:grid` + `justify-items`/`align-items` from the
 /// grid `ALIGNMENT` (cells position within their tracks; default Leading/start),
 /// plus the fixed track templates — a `GRID_TRACKS` spec (per-track sizes) or
 /// `columns` (GRID/LAZY_VGRID; the effective count) and `HEIGHT` rows
 /// (GRID/LAZY_HGRID) as equal `1fr` tracks. `FILL`/absent count = auto-fit (no
 /// template; `LAZY_HGRID` columns auto-flow).
 fn grid_style(node: &Node, columns: Option<u32>) -> String {
     let align = node.f32_property(property_id::ALIGNMENT, 0.0) as u8;
     let mut css = format!(
         "display:grid;justify-items:{};align-items:{};",
         align_h(align),
         align_v(align)
     );
     let tracks_css = grid_tracks_css(node);
     match node.component {
         component_type::GRID => {
             if let Some(t) = &tracks_css {
                 css.push_str(&format!("grid-template-columns:{t};"));
             } else if let Some(n) = columns {
                 css.push_str(&format!("grid-template-columns:repeat({n},minmax(0,1fr));"));
             }
             if let Some(n) = grid_rows(node) {
                 css.push_str(&format!("grid-template-rows:repeat({n},minmax(0,1fr));"));
             }
         }
         component_type::LAZY_HGRID => {
             if let Some(t) = &tracks_css {
                 css.push_str(&format!("grid-template-rows:{t};"));
             } else if let Some(n) = grid_rows(node) {
                 css.push_str(&format!("grid-template-rows:repeat({n},minmax(0,1fr));"));
             }
             css.push_str("grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);");
         }
         _ => {
             if let Some(t) = &tracks_css {
                 css.push_str(&format!("grid-template-columns:{t};"));
             } else if let Some(n) = columns {
                 css.push_str(&format!("grid-template-columns:repeat({n},minmax(0,1fr));"));
             }
         }
     }
     css
 }

 /// A `style="…"` attribute for a non-empty CSS fragment.
 fn style_attr(css: &str) -> String {
     if css.is_empty() {
         String::new()
     } else {
         format!(" style=\"{css}\"")
     }
 }

 /// A `class="…"` attribute for a non-empty class list.
 fn class_attr(classes: &str) -> String {
     let classes = classes.trim();
     if classes.is_empty() {
         String::new()
     } else {
         format!(" class=\"{classes}\"")
     }
 }

 /// Escape text for inclusion in an HTML body.
 fn escape(input: &str) -> String {
     input
         .replace('&', "&amp;")
         .replace('<', "&lt;")
         .replace('>', "&gt;")
         .replace('"', "&quot;")
         .replace('\'', "&#39;")
 }

 /// Render attributed text as escaped, non-overlapping `<span>`/`<a>` segments.
 fn render_attributed(value: &pathland_core::AttributedString) -> String {
     let text = value.text();
     let mut out = String::new();
     for segment in value.segments() {
         let body = escape(&text[segment.start as usize..segment.end as usize]);
         let css = run_style_css(&segment.attributes);
         let rendered = match segment.link {
             Some(url) => {
                 let style = if css.is_empty() {
                     String::new()
                 } else {
                     format!(" style=\"{}\"", escape_html_attr(&css))
                 };
                 format!("<a href=\"{}\"{style}>{body}</a>", escape_html_attr(url))
             }
             None if css.is_empty() => body,
             None => format!("<span style=\"{}\">{body}</span>", escape_html_attr(&css)),
         };
         out.push_str(&rendered);
     }
     out
 }

 /// The v1 run attributes as inline CSS.
 fn run_style_css(attributes: &[pathland_core::TextAttribute]) -> String {
     let mut css = String::new();
     let mut underline = false;
     let mut strikethrough = false;
     for attr in attributes {
         match attr.property {
             property_id::FONT_SIZE => {
                 let value = f32::from_bits(attr.value);
                 if value > 0.0 {
                     css.push_str(&format!("font-size:{value}px;"));
                 }
             }
             property_id::FONT_WEIGHT => {
                 let value = f32::from_bits(attr.value);
                 if value > 0.0 {
                     css.push_str(&format!("font-weight:{value};"));
                 }
             }
             property_id::COLOR => css.push_str(&format!("color:{};", rgba(attr.value))),
             property_id::FONT_STYLE => {
                 if f32::from_bits(attr.value) as u8 == 1 {
                     css.push_str("font-style:italic;");
                 }
             }
             property_id::FONT_DESIGN => {
                 let family = match f32::from_bits(attr.value) as u8 {
                     1 => "Georgia, 'Times New Roman', serif",
                     2 => "ui-rounded, system-ui, sans-serif",
                     3 => "ui-monospace, monospace",
                     _ => "inherit",
                 };
                 css.push_str(&format!("font-family:{family};"));
             }
             property_id::UNDERLINE => underline |= attr.value != 0,
             property_id::STRIKETHROUGH => strikethrough |= attr.value != 0,
             _ => {}
         }
     }
     if underline || strikethrough {
         let mut decoration = Vec::new();
         if underline {
             decoration.push("underline");
         }
         if strikethrough {
             decoration.push("line-through");
         }
         css.push_str(&format!("text-decoration:{};", decoration.join(" ")));
     }
     css
 }

 /// Slot attributes for a navigation/conditional slot node: the current path as
 /// `data-pathland-route` (the DOM client mirrors it into the URL), the
 /// `data-pathland-transition` swap hint (`platform`/`fade`/`slide`/`scale`),
 /// and the `data-pathland-nav-chrome` chrome mode (`custom` only — the default
 /// is the renderer's own chrome, so it is omitted). Empty for ordinary nodes.
 /// See `spec/DSL.md` §4.5 and `spec/MODIFIERS.md`.
 fn slot_attrs(node: &Node) -> String {
     let mut attrs = String::new();
     if let Some(path) = node.strings.get(&property_id::ROUTE) {
         attrs.push_str(&format!(" data-pathland-route=\"{}\"", escape(path)));
     }
     let chrome = node.f32_property(property_id::NAV_CHROME, 0.0).round() as u8;
     if chrome == 1 {
         attrs.push_str(" data-pathland-nav-chrome=\"custom\"");
     }
     // Back-stack depth: lets the DOM client hydrate the renderer's default back
     // button (shown when a PlatformDefault slot is deeper than its root) from the
     // SSR HTML before any delta frame arrives.
     let depth = node.u32_property(property_id::NAV_DEPTH, 1).max(1);
     if depth > 1 {
         attrs.push_str(&format!(" data-pathland-depth=\"{depth}\""));
     }
     let transition = node.f32_property(property_id::TRANSITION, 0.0).round() as u8;
     if transition != 0 {
         let name = match transition {
             2 => "fade",
             3 => "slide",
             4 => "scale",
             _ => "platform",
         };
         attrs.push_str(&format!(" data-pathland-transition=\"{name}\""));
     }
     attrs
 }

