 /**
  * Re-establish focus after a structural batch.
  *
  * A keyed lazy window slides by removing rows above the viewport and then
  * MOVING every surviving row to its new index. Moving a focused element
  * (removeChild + insertBefore) blurs it in Chromium/WebKit, so keyboard
  * navigation inside a scrolling list would silently drop focus and the next
  * arrow key would go nowhere. The app's explicit `SET_FOCUS` request still wins;
  * otherwise we restore the element that was focused before the batch.
  */
 function restoreFocus(
   snapshot: FocusSnapshot | null,
   explicit: HTMLElement | null | undefined,
 ): void {
   const target = explicit === undefined ? snapshot?.element ?? null : explicit;
   if (!target || !target.isConnected) {
     return;
   }
   if (document.activeElement !== target) {
     target.focus({ preventScroll: true });
   }
   if (
     snapshot &&
     target === snapshot.element &&
     snapshot.start !== null &&
     snapshot.end !== null &&
     (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement)
   ) {
     try {
       target.setSelectionRange(snapshot.start, snapshot.end, snapshot.direction ?? undefined);
     } catch {
       // The control type may not support selection ranges.
     }
   }
 }

 /** Apply every opcode in a batch to the DOM (TREE structure + PARAMETER/META deltas). */
 export function applyBatch(batch: Batch, renderer: DomRenderer): void {
   validateBatch(batch, renderer);
   const focusSnapshot = captureFocus();
   // `undefined` = no focus request in this batch; `null` = explicit blur/invalid.
   let explicitFocus: HTMLElement | null | undefined;
   // SSR snapshot fit slots (`data-pathland-fit-cands`) touched by a structural
   // removal in this batch. The gate is torn down AFTER the whole batch, gated on
   // the slot's FINAL state (issue #141): a removal that does NOT reduce the slot
   // to a single live candidate (e.g. a band-crossing fit swap dropping a child
   // inside a candidate) must leave the gate intact — unwrapping it eagerly would
   // expose every candidate (the "all branches rendered" bug).
   const touchedFitGates = new Set<HTMLElement>();
   for (let i = 0; i < batch.opcodes.length; i++) {
     const op = batch.opcodes[i]!;
     try {
       switch (op.category) {
         case CAT_TREE:
           applyTree(op, renderer, touchedFitGates);
           break;
         case CAT_PARAMETER:
           applyStyle(op, batch.strings, renderer);
           break;
         case CAT_META:
           applyMeta(op, batch.strings, renderer);
           if (op.command === CMD_SET_FOCUS) {
             const target = op.b !== 0 ? renderer.byId.get(op.a) : null;
             explicitFocus = target instanceof HTMLElement ? target : null;
           }
           break;
         default:
           break;
       }
     } catch (err) {
       // The batch is a renderer-consuming instruction stream; an empty catch
       // would hide a structural bug. Log the exact op for remote diagnosis,
       // then rethrow (the host's handleMessage surfaces it).
       const el = renderer.byId.get(op.a);
       const where = el instanceof Element
         ? `${el.tagName.toLowerCase()}#${el.getAttribute("data-pathland-id")}.${el.className}`
         : String(el);
       console.error(
         `[pathland] applyBatch failed at op ${i}/${batch.opcodes.length} ` +
         `cat=${op.category} cmd=${op.command} a=${op.a} b=${op.b} c=${op.c} target=${where}`, err);
       throw err;
     }
   }
   for (const slot of touchedFitGates) {
     reconcileFitGate(slot);
   }
   // Derived layout (fill propagation, ZStack sizing/positioning, cross-axis
   // align-self) — mirrors the Rust SSR renderer's whole-tree decisions.
   applyLayout(renderer);
   // Restore focus before reporting lazy ranges: a row move must not turn into a
   // spurious `FOCUS_CHANGED(false)` that lets a scroll report reset the app's
   // focused index.
   restoreFocus(focusSnapshot, explicitFocus);
   refreshLazyWindows(renderer);
   // A reconnect replacement rebuilds the tree from scratch; restore any captured
   // scroll offsets once their (re-created) elements exist, then re-report the
   // lazy windows from the restored position.
   if (restorePendingScroll(renderer)) {
     refreshLazyWindows(renderer, true);
   }
 }

 /**
  * Discard the renderer's retained output (its own cache of the opcode stream).
  *
  * A reconnect creates a fresh server session, so the previous tree's ids and
  * lazy window no longer describe the same nodes. The resync snapshot is a mount
  * stream for the new tree; applying it as an in-place merge would leave stale
  * rows (the scrambled lazy-list bug). Reset first, then rebuild from the
  * snapshot. This clears rendered output only — application state lives on the
  * server, and renderer-global theme/token overrides survive.
  *
  * `captureScroll` records scroll offsets for the replacement pass; an explicit
  * `META::RESET` (the server asking for a clean slate) does not restore them.
  */
 export function resetRenderedOutput(r: DomRenderer, captureScroll = true): void {
   pendingScrollRestore.clear();
   if (captureScroll) {
     for (const [id, el] of r.byId) {
       if (!(el instanceof HTMLElement)) {
         continue;
       }
       const left = el.scrollLeft;
       const top = el.scrollTop;
       if ((left > 0 || top > 0) && Number.isFinite(left) && Number.isFinite(top)) {
         pendingScrollRestore.set(id, { left, top });
       }
     }
   }
   for (const el of Array.from(r.byId.values())) {
     if (el instanceof Element) {
       purgeSubtreeRegistry(el, r);
     }
     if (el.parentNode) {
       el.parentNode.removeChild(el);
     }
   }
   r.byId.clear();
   // Controller ids belong to the replaced tree; the new snapshot re-creates them.
   mediaRegistry.clear();
 }

