+    applyBatch(parseBatch(buildBatch([[CAT_META, CMD_SET_FOCUS, 0, 1, 1]])), r);
+
+    expect(focus).toHaveBeenCalledWith({ preventScroll: true });
+    expect(reveal).toHaveBeenCalledWith({
+      block: "nearest",
+      inline: "nearest",
+      behavior: expect.stringMatching(/^(auto|smooth)$/),
